#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 4); //Устанавливаем ЖК-дисплей по адресу 0x27, 16 символов и 2 строки
const int potPin = A1;  // пин, к которому подключён потенциометр
int potValue = 0;       // переменная для хранения значения


void setup() {
//Serial.begin(9600);

lcd.init(); //Инициализируем ЖК-дисплей
lcd.backlight();// Включаем подсветку дисплея
lcd.clear();
lcd.setCursor(0, 0);              //Устанавливаем курсор на первую строку и нулевой символ
lcd.print("micro-pi.ru");         //Выводим на экран строку
delay(1000);
}

void loop() {
  //potValue = analogRead(potPin);    // считываем значение (0–1023)
  //Serial.println(potValue);         // выводим в монитор порта

   //lcd.clear();
   potValue = analogRead(potPin);    // считываем значение (0–1023)

   lcd.setCursor(0, 1);
   lcd.print("micro:");
   lcd.print("        ");
   lcd.setCursor(0, 1);
   lcd.print("micro:");
   lcd.print(potValue);

  delay(100);

}
